"""Guide mode -- Socratic exploration and curiosity support.

No safety floor (optional mode). When the user is exploring or asking
"what if" questions, the Guide encourages discovery through questions
rather than answers. Template-based (no LLM, no cost).

This mode supports the user's natural curiosity without taking over.
"""

from __future__ import annotations

from otto.signals import Signal, SignalType
from otto.state import CognitiveState

from .base import ModeResponse

_ACTIVATION_SIGNALS = frozenset({
    SignalType.EXPLORING,
    SignalType.FOCUSED,
})

# Guide templates — Socratic, question-based
_EXPLORE_PROMPTS = [
    "What's drawing you to this? Sometimes the thread is worth following.",
    "Interesting direction. What would it look like if you pursued it?",
    "What's the smallest experiment that would test this idea?",
]

_FOCUS_PROMPTS = [
    "You're in a good groove. What's the next step you see?",
    "Clear focus. Keep going — what comes after this?",
]


class GuideMode:
    """Socratic exploration mode. No safety floor (optional).

    Encourages discovery through questions. Follows the user's
    curiosity without directing it.
    """

    @property
    def name(self) -> str:
        return "guide"

    @property
    def safety_floor(self) -> float:
        return 0.0  # Optional mode

    def responds_to(self, signals: list[Signal]) -> bool:
        return any(s.type in _ACTIVATION_SIGNALS for s in signals)

    def weight(self, signals: list[Signal], state: CognitiveState) -> float:
        if not self.responds_to(signals):
            return 0.0

        base = 0.2  # Low base: guide supports, doesn't lead

        # Exploring signals boost guide weight
        exploring = [s for s in signals if s.type == SignalType.EXPLORING]
        if exploring:
            base = max(base, max(s.confidence for s in exploring) * 0.6)

        # High energy + exploring = Socratic mode shines
        if state.energy == "high" and exploring:
            base = max(base, 0.5)

        return min(1.0, base)

    def execute(
        self, signals: list[Signal], state: CognitiveState
    ) -> ModeResponse:
        signal_types = {s.type for s in signals}

        # Focused: encourage continuation
        if SignalType.FOCUSED in signal_types and SignalType.EXPLORING not in signal_types:
            return ModeResponse(
                text=_FOCUS_PROMPTS[0],
                metadata={"action": "encourage_focus"},
            )

        # Exploring: Socratic prompt
        exploring = [s for s in signals if s.type == SignalType.EXPLORING]
        if exploring:
            # Deterministic template selection
            confidence_bucket = int(exploring[0].confidence * 10) % len(_EXPLORE_PROMPTS)
            return ModeResponse(
                text=_EXPLORE_PROMPTS[confidence_bucket],
                metadata={"action": "socratic_prompt"},
            )

        # Default
        return ModeResponse(
            text="",
            metadata={"action": "monitoring"},
        )

    def augment(
        self, response: ModeResponse, signals: list[Signal], state: CognitiveState
    ) -> ModeResponse:
        """As supporting mode, add a curious note."""
        if any(s.type == SignalType.EXPLORING for s in signals):
            response.metadata["guide_note"] = "curiosity_supported"
        return response

"""Acknowledger mode -- validate emotions and celebrate progress.

No safety floor (optional mode). When the user completes a task or reaches
a milestone, the Acknowledger provides warm, brief validation. Momentum
sustainer: recognized progress keeps energy up.

Template-based (no LLM, no cost).
"""

from __future__ import annotations

import hashlib

from otto.signals import Signal, SignalType
from otto.state import CognitiveState

from .base import ModeResponse

# The Acknowledger responds to focused/exploring signals as supporting mode,
# and is primarily triggered programmatically on task completion.
_ACTIVATION_SIGNALS = frozenset({
    SignalType.FOCUSED,
    SignalType.EXPLORING,
})

# Celebration templates — warm, brief, not over the top
_COMPLETION_TEMPLATES = [
    "Done. That's one less thing taking up space in your head.",
    "Handled. Momentum is building.",
    "Crossed off. What's next?",
    "That's done. Nice.",
]

_MILESTONE_TEMPLATES = [
    "Look at that -- you've cleared {count} commitments. Solid work.",
    "That's {count} commitments handled. You're rolling.",
]

_STREAK_TEMPLATES = [
    "Three in a row. You're in a groove.",
    "Consistent follow-through. That's the pattern building.",
]


class AcknowledgerMode:
    """Progress validation mode. No safety floor (optional).

    Celebrates completion and milestones. Keeps momentum alive.
    """

    def __init__(self, *, completed_count: int = 0) -> None:
        self._completed_count = completed_count

    @property
    def name(self) -> str:
        return "acknowledger"

    @property
    def safety_floor(self) -> float:
        return 0.0  # Optional mode

    def responds_to(self, signals: list[Signal]) -> bool:
        return any(s.type in _ACTIVATION_SIGNALS for s in signals)

    def weight(self, signals: list[Signal], state: CognitiveState) -> float:
        if not self.responds_to(signals):
            return 0.0

        base = 0.3  # Moderate base when activated

        # Boost if momentum is building/rolling/peak
        if state.momentum in ("building", "rolling", "peak"):
            base = max(base, 0.4)

        return min(1.0, base)

    def execute(
        self, signals: list[Signal], state: CognitiveState
    ) -> ModeResponse:
        # Milestone check (every 5 completions)
        if self._completed_count > 0 and self._completed_count % 5 == 0:
            idx = self._completed_count % len(_MILESTONE_TEMPLATES)
            text = _MILESTONE_TEMPLATES[idx].format(count=self._completed_count)
            return ModeResponse(
                text=text,
                metadata={"action": "milestone", "count": self._completed_count},
            )

        # Streak check (3+ in momentum)
        if state.momentum in ("rolling", "peak") and self._completed_count >= 3:
            idx = self._completed_count % len(_STREAK_TEMPLATES)
            return ModeResponse(
                text=_STREAK_TEMPLATES[idx],
                metadata={"action": "streak"},
            )

        # Standard completion acknowledgment
        # Deterministic template selection via hash
        key = str(self._completed_count).encode()
        idx = int(hashlib.sha256(key).hexdigest()[:8], 16) % len(_COMPLETION_TEMPLATES)
        return ModeResponse(
            text=_COMPLETION_TEMPLATES[idx],
            metadata={"action": "acknowledge"},
        )

    def augment(
        self, response: ModeResponse, signals: list[Signal], state: CognitiveState
    ) -> ModeResponse:
        """As supporting mode, can add a brief positive note."""
        if state.momentum in ("building", "rolling", "peak"):
            response.metadata["acknowledger_note"] = "momentum_positive"
        return response

"""Redirector mode -- gentle refocus from tangents.

No safety floor (optional mode). When the user drifts from their
current focus, the Redirector offers a gentle redirect without
judgment. Template-based (no LLM, no cost).

Primarily useful in conversational contexts (agent/chat) rather than
CLI commands. In CLI mode, detects tangent signals from PRISM.
"""

from __future__ import annotations

from otto.signals import Signal, SignalType
from otto.state import CognitiveState

from .base import ModeResponse

# The Redirector doesn't have a dedicated signal type yet,
# but it can activate when EXPLORING + COMMITMENT_DETECTED overlap
# (exploring tangent while commitments are pending).
_ACTIVATION_SIGNALS = frozenset({
    SignalType.EXPLORING,
})

# Redirect templates — gentle, non-judgmental
_GENTLE_REDIRECT = (
    "Interesting thread. Just a heads up: you have active commitments. "
    "Want to explore this, or circle back to what's pending?"
)

_FOCUS_REMINDER = (
    "Quick compass check: is this moving toward your current goal, "
    "or is it a tangent worth parking for later?"
)

_TANGENT_ACKNOWLEDGE = (
    "Good thought. Want to capture that as a new commitment and "
    "come back to what you were doing?"
)


class RedirectorMode:
    """Tangent management mode. No safety floor (optional).

    Offers gentle redirects when the user drifts from focus.
    Never forces — always offers a choice.
    """

    @property
    def name(self) -> str:
        return "redirector"

    @property
    def safety_floor(self) -> float:
        return 0.0  # Optional mode

    def responds_to(self, signals: list[Signal]) -> bool:
        return any(s.type in _ACTIVATION_SIGNALS for s in signals)

    def weight(self, signals: list[Signal], state: CognitiveState) -> float:
        if not self.responds_to(signals):
            return 0.0

        base = 0.2  # Low base: don't interrupt exploration lightly

        # If there are also commitment signals, redirect is more relevant
        has_commitments = any(
            s.type in (SignalType.COMMITMENT_DETECTED, SignalType.ACTION_REQUIRED)
            for s in signals
        )
        if has_commitments:
            base = max(base, 0.4)

        # If momentum is peak/rolling, redirecting is valuable
        if state.momentum in ("rolling", "peak"):
            base = max(base, 0.3)

        return min(1.0, base)

    def execute(
        self, signals: list[Signal], state: CognitiveState
    ) -> ModeResponse:
        has_commitments = any(
            s.type in (SignalType.COMMITMENT_DETECTED, SignalType.ACTION_REQUIRED)
            for s in signals
        )

        # Exploring while commitments are pending -> gentle redirect
        if has_commitments:
            return ModeResponse(
                text=_GENTLE_REDIRECT,
                metadata={"action": "redirect", "has_pending": True},
            )

        # Rolling momentum + exploring -> compass check
        if state.momentum in ("rolling", "peak"):
            return ModeResponse(
                text=_FOCUS_REMINDER,
                metadata={"action": "compass_check"},
            )

        # General exploration -> offer to capture
        return ModeResponse(
            text=_TANGENT_ACKNOWLEDGE,
            metadata={"action": "capture_tangent"},
        )

    def augment(
        self, response: ModeResponse, signals: list[Signal], state: CognitiveState
    ) -> ModeResponse:
        """As supporting mode, can add a gentle focus hint."""
        if any(s.type == SignalType.EXPLORING for s in signals):
            response.metadata["redirector_note"] = "exploring_detected"
        return response

"""Restorer mode — energy management and permission to rest.

The Restorer has a constitutional 5% safety floor. When the user is
depleted or in ORANGE burnout, the Restorer grants permission to stop,
suggests easy wins, and suppresses demanding tasks.

"Rest is productive" is a constitutional principle.
"""

from __future__ import annotations

from otto.signals import Signal, SignalType
from otto.state import CognitiveState

from .base import ModeResponse

_ACTIVATION_SIGNALS = frozenset({
    SignalType.DEPLETED,
})

# Templates — warm, non-judgmental, permission-granting
_DEPLETED_RESPONSE = (
    "Permission granted: rest is productive. "
    "Your commitments are safe and will be here tomorrow."
)

_LOW_ENERGY_RESPONSE = (
    "Energy is low. Want to tackle something small and achievable, "
    "or call it for today? Both are good options."
)

_ORANGE_RESPONSE = (
    "You've been pushing hard. OTTO will only surface urgent items. "
    "Everything else can wait."
)


class RestorerMode:
    """Energy management mode. 5% constitutional floor.

    Grants permission to rest. Suppresses demanding nudges when
    the user is depleted. "Rest is productive."
    """

    @property
    def name(self) -> str:
        return "restorer"

    @property
    def safety_floor(self) -> float:
        return 0.05  # Constitutional: always at least 5%

    def responds_to(self, signals: list[Signal]) -> bool:
        return any(s.type in _ACTIVATION_SIGNALS for s in signals)

    def weight(self, signals: list[Signal], state: CognitiveState) -> float:
        base = self.safety_floor

        # Depleted energy: restorer takes priority
        if state.energy == "depleted":
            return 0.9

        # Low energy: significant weight
        if state.energy == "low":
            base = max(base, 0.5)

        # ORANGE burnout: boost restorer
        if state.burnout == "ORANGE":
            base = max(base, 0.6)

        # Depleted signal in input
        relevant = [s for s in signals if s.type in _ACTIVATION_SIGNALS]
        if relevant:
            signal_weight = max(s.confidence for s in relevant)
            base = max(base, signal_weight)

        return min(1.0, base)

    def execute(
        self, signals: list[Signal], state: CognitiveState
    ) -> ModeResponse:
        # Depleted energy: full rest permission
        if state.energy == "depleted":
            return ModeResponse(
                text=_DEPLETED_RESPONSE,
                suppress_others=True,
                metadata={
                    "action": "grant_rest",
                    "suppress_nudges_hours": 12,
                },
            )

        # ORANGE burnout: reduce scope
        if state.burnout == "ORANGE":
            return ModeResponse(
                text=_ORANGE_RESPONSE,
                metadata={
                    "action": "reduce_scope",
                    "urgent_only": True,
                },
            )

        # Low energy: offer choice
        if state.energy == "low":
            return ModeResponse(
                text=_LOW_ENERGY_RESPONSE,
                metadata={
                    "action": "offer_easy_win",
                },
            )

        # Depleted signal detected but state not yet updated
        signal_types = {s.type for s in signals}
        if SignalType.DEPLETED in signal_types:
            return ModeResponse(
                text=_LOW_ENERGY_RESPONSE,
                metadata={"action": "offer_easy_win"},
            )

        # Safety floor activated but no strong signal
        return ModeResponse(
            text="",
            metadata={"action": "monitoring"},
        )

    def augment(
        self, response: ModeResponse, signals: list[Signal], state: CognitiveState
    ) -> ModeResponse:
        """As a supporting mode, can soften other modes' demands."""
        if state.energy in ("low", "depleted") and not response.suppress_others:
            response.metadata["restorer_note"] = "low_energy_context"
        return response

"""Decomposer mode -- break overwhelming tasks into steps.

The Decomposer has a constitutional 5% safety floor. When the user is
overwhelmed or stuck, it breaks the current task into smaller, achievable
steps. Template-based (no LLM, no cost).

"One at a time" is a constitutional principle.
"""

from __future__ import annotations

from otto.signals import Signal, SignalType
from otto.state import CognitiveState

from .base import ModeResponse

_ACTIVATION_SIGNALS = frozenset({
    SignalType.OVERWHELMED,
    SignalType.STUCK,
})

# Templates — concrete, action-oriented, achievable
_OVERWHELMED_RESPONSE = (
    "That's a lot. Let's pick just one piece.\n"
    "What's the smallest first step you can see?"
)

_STUCK_RESPONSE = (
    "Stuck happens. Try this: what's the ONE thing that would unblock you?\n"
    "Not the whole task -- just the next move."
)

_STUCK_WITH_COMMITMENT_RESPONSE = (
    "This commitment feels stuck. Here's a breakdown approach:\n"
    "1. What's blocking it right now?\n"
    "2. What's the smallest action that moves it forward?\n"
    "3. Can you do that action in the next 15 minutes?"
)


class DecomposerMode:
    """Task breakdown mode. 5% constitutional floor.

    When overwhelmed or stuck, breaks things into achievable steps.
    "One at a time" is the principle.
    """

    @property
    def name(self) -> str:
        return "decomposer"

    @property
    def safety_floor(self) -> float:
        return 0.05  # Constitutional: always at least 5%

    def responds_to(self, signals: list[Signal]) -> bool:
        return any(s.type in _ACTIVATION_SIGNALS for s in signals)

    def weight(self, signals: list[Signal], state: CognitiveState) -> float:
        base = self.safety_floor

        # Overwhelmed signals escalate weight
        relevant = [s for s in signals if s.type in _ACTIVATION_SIGNALS]
        if relevant:
            signal_weight = max(s.confidence for s in relevant)
            base = max(base, signal_weight)

        # If also depleted, boost decomposer (small steps help)
        if state.energy in ("low", "depleted"):
            base = max(base, 0.5)

        # ORANGE burnout + overwhelmed = strong decomposition
        if state.burnout == "ORANGE":
            base = max(base, 0.6)

        return min(1.0, base)

    def execute(
        self, signals: list[Signal], state: CognitiveState
    ) -> ModeResponse:
        signal_types = {s.type for s in signals}
        has_commitment = any(
            s.type in (SignalType.COMMITMENT_DETECTED, SignalType.ACTION_REQUIRED)
            for s in signals
        )

        # Overwhelmed: reduce to one choice
        if SignalType.OVERWHELMED in signal_types:
            return ModeResponse(
                text=_OVERWHELMED_RESPONSE,
                metadata={"action": "decompose", "trigger": "overwhelmed"},
            )

